const expected = ["workflow_status", "post_note", "claim_paths", "release_paths"];
const found = expected.map(suffix => ALL_TOOLS.find(t => t.name.includes("ctrlyoke") && t.name.endsWith(suffix)));
if (found.some(x => !x)) throw new Error("Required ctrlyoke tool not found");
const methods = found.map(x => x.name.replace(/[^a-zA-Z0-9_]/g, "_"));
const results = [];
results.push(await tools[methods[0]]({}));
results.push(await tools[methods[1]]({text:"mcp probe note"}));
results.push(await tools[methods[2]]({paths:["probe.txt"],reason:"mcp probe"}));
results.push(await tools[methods[3]]({paths:["probe.txt"]}));
text("Completed four ctrlyoke calls.");
